  renderBoard(){const d=this.doc.data,library=this.element.querySelector('.gameplay-library'),main=this.element.querySelector('.gameplay-main');library.innerHTML='<h3>키 자료형</h3>'+Object.keys(boardTypes).map(type=>`<button data-add-key="${type}">${icon('plus')}${type}</button>`).join('');main.innerHTML='<div class="gameplay-key-list"><h3>블랙보드</h3>'+d.keys.map((key,i)=>`<section>${this.field('이름','keys.'+i+'.name',key.name)}${this.field('자료형','keys.'+i+'.type',key.type,'text',Object.keys(boardTypes).map(t=>[t,t]))}${this.field('기본값','keys.'+i+'.value',key.value,key.type==='object'?'object':'json')}<button data-delete-key="${i}" aria-label="${esc(key.name)} 삭제">${icon('close')}</button></section>`).join('')+'</div>';}
